// ===== Helpers =====

fn format_size(bytes: u64, format: Option<&str>) -> String {
    match format {
        None => format_human(bytes, 1024),
        Some("si") => format_human(bytes, 1000),
        Some("b") => format!("{}B", bytes),
        Some("k") => format!("{}K", bytes / 1024),
        Some("m") => format!("{}M", bytes / (1024*1024)),
        Some("g") => format!("{}G", bytes / (1024*1024*1024)),
        Some("t") => format!("{}T", bytes / (1024u64*1024*1024*1024)),
        Some("kb") => format!("{}K", bytes / 1000),
        Some("mb") => format!("{}M", bytes / (1000*1000)),
        Some("gb") => format!("{}G", bytes / (1000*1000*1000)),
        Some("tb") => format!("{}T", bytes / (1000u64*1000*1000*1000)),
        Some(_) => format_human(bytes, 1024),
    }
}

fn format_human(bytes: u64, base: u64) -> String {
    if bytes < base {
        return format!("{}B", bytes);
    }
    let units = ["B", "K", "M", "G", "T", "P"];
    let mut size = bytes as f64;
    let mut unit_idx = 0;
    // Find appropriate unit: while size >= base and not last unit, but need to handle threshold correctly
    // For base 1024: 1023 -> B, 1024 -> K; for base 1000: 999 -> B, 1000 -> K
    // So divide while bytes >= base^(unit_idx+1)
    let mut threshold = base;
    while unit_idx + 1 < units.len() {
        if bytes < threshold * base && unit_idx > 0 {
            break;
        }
        if bytes < threshold && unit_idx == 0 {
            break;
        }
        // Actually simpler: determine unit by thresholds
        break;
    }
    // Determine unit index by thresholds
    let mut idx = 0;
    let mut div: u64 = 1;
    // B: < base, K: < base^2, M: < base^3, etc.
    // So find largest idx such that bytes >= base^idx (for idx>0) and bytes < base^(idx+1) ?
    // For bytes < base => idx 0 (B)
    // Else idx 1 (K) if bytes < base^2, etc.
    if bytes >= base {
        idx = 1;
        div = base;
        // check higher
        let mut pow = base * base; // base^2
        let mut i = 2;
        while i < units.len() {
            if bytes < pow {
                break;
            }
            idx = i;
            div = pow / base * 1; // div = base^i ? Let's compute: for M (i=2), div should be base^2
            // Actually div for unit idx is base^idx
            // For K idx1 div=base^1, M idx2 div=base^2, etc.
            // pow is base^(i) ? For i=2, pow=base^2, so div=pow? No, for M we need base^2, which is pow. Good.
            // But we set div above incorrectly. Let's recompute properly below.
            i += 1;
            if pow > u64::MAX / base { break; }
            pow *= base;
        }
        // Recompute div as base^idx
        div = 1;
        for _ in 0..idx { div *= base; }
    }
    if idx == 0 {
        return format!("{}B", bytes);
    }
    let val = bytes as f64 / div as f64;
    if val < 10.0 {
        // one decimal, rounded
        // Format with one decimal, but need to handle e.g., 9.999 -> 10.0 (still one decimal)
        format!("{:.1}{}", val, units[idx])
    } else {
        // integer, rounded? Actually for >=10, show integer rounded? Check: 10.74 -> 10? 9.765 with <10 shows 9.8, but >=10 shows integer. How to round? e.g., 15000/1024=14.648 -> 14? Earlier 15000 default 14K (14.648->14? Rounded? 14.648 rounded =15, but actual 14. So truncated? Or rounded? Let's see: 15000/1024=14.648, actual 14K (floor). 20000/1024=19.53->19K (floor). 100000/1024=97.65->97K (floor). So for >=10, it truncates (floor), not rounds? Check 11264/1024=11.0 exactly ->11K. 11500/1024=11.23->11K (floor or round both 11). Need case where floor vs round differ: 15000 gave 14 (floor, round would be 15). So floor. Good. So for >=10, floor.
        // But what about 10239/1024=9.999 -> shows 10.0K (one decimal, since <10 before rounding, but after rounding 10.0). That's handled by <10 branch (one decimal). Good.
        // For >=10, floor.
        let floored = val.floor() as u64;
        format!("{}{}", floored, units[idx])
    }
}

fn parse_min_size(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }
    // Try to parse number + suffix
    // Suffix can be: B, K, M, G, T (case-insensitive?), with optional B? e.g., KB, MB? Also K vs k?
    // From tests: 1K, 1k, 1M, 1m, 100, 100B, 100b, 1G, 1g, 1KB all worked.
    // Need to determine multipliers: K/k/KB/kb => 1024? Or 1000 for si? For min-size, does it use 1024 or 1000? Likely 1024 for K,M,G and 1000 for KB,MB? Or all 1024? Let's test: min-size 1K vs 1KB vs 1000 vs 1024 with files of known sizes to see thresholds.
    // For now, implement: B/b => 1, K/k => 1024, M/m => 1024*1024, G/g => 1024^3, T/t => 1024^4, with optional trailing B/b (e.g., KB, K, kB all same?).
    // Also handle plain number (bytes).
    let mut num_part = String::new();
    let mut suffix_part = String::new();
    for c in s.chars() {
        if c.is_ascii_digit() && suffix_part.is_empty() {
            num_part.push(c);
        } else {
            suffix_part.push(c);
        }
    }
    if num_part.is_empty() { return None; }
    let num: u64 = num_part.parse().ok()?;
    let suffix = suffix_part.trim().to_lowercase();
    let mult: u64 = if suffix.is_empty() || suffix == "b" {
        1
    } else if suffix == "k" || suffix == "kb" || suffix == "kib" {
        1024
    } else if suffix == "m" || suffix == "mb" || suffix == "mib" {
        1024*1024
    } else if suffix == "g" || suffix == "gb" || suffix == "gib" {
        1024*1024*1024
    } else if suffix == "t" || suffix == "tb" || suffix == "tib" {
        1024u64*1024*1024*1024
    } else {
        // Invalid suffix like "foo" (num=?? Actually "foo" has no num, already returned None. For "1foo", suffix "foo" invalid => None (ignore)
        return None;
    };
    num.checked_mul(mult)
}

