// ===== Terminal size =====
fn get_terminal_size() -> (Option<usize>, Option<usize>) {
    // Try stdout (fd 1), stderr (fd 2), stdin (fd 0) via ioctl TIOCGWINSZ
    // Return (width, height)
    use std::os::unix::io::AsRawFd;
    for fd in [1, 2, 0] {
        let mut winsz: libc::winsize = unsafe { std::mem::zeroed() };
        let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsz) };
        if ret == 0 && winsz.ws_col != 0 && winsz.ws_row != 0 {
            return (Some(winsz.ws_col as usize), Some(winsz.ws_row as usize));
        }
    }
    (None, None)
}

fn is_any_terminal() -> bool {
    // Check if stdout, stderr, or stdin is a tty (for colors)
    unsafe {
        libc::isatty(1) == 1 || libc::isatty(2) == 1 || libc::isatty(0) == 1
    }
}

