    let mut parts: Vec<std::ffi::OsString> = Vec::new();
    let is_abs = p.is_absolute();
    for comp in p.components() {
        use std::path::Component;
        match comp {
            Component::CurDir => {},
            Component::ParentDir => {
                if !parts.is_empty() {
                    parts.pop();
                } else if !is_abs {
                    parts.push(std::ffi::OsString::from(".."));
                }
            },
            Component::Normal(s) => parts.push(s.to_os_string()),
            Component::RootDir => {},
            Component::Prefix(p) => parts.push(p.as_os_str().to_os_string()),
        }
    }
    let mut res = PathBuf::new();
    if is_abs { res.push("/"); }
    for part in parts { res.push(part); }
    if res.as_os_str().is_empty() {
        if is_abs { PathBuf::from("/") } else { PathBuf::from(".") }
    } else {
        res
    }
}

